            vm.startPrank(user2);
            _asset.approve(address(_lmpVault), 1000);
            _lmpVault.deposit(1000, user2);
            vm.stopPrank();

            assert(_toke.balanceOf(attacker) == 0);
            assert(_toke.balanceOf(address(this)) == 0);
